		val __ca1: NodeSnapshot? = s!!.nodes
		this.nodes = if (__ca1 === null) null else __ca1!!.Clone()
		val __ca2: LinkSnapshot? = s!!.links
		this.links = if (__ca2 === null) null else __ca2!!.Clone()
		val __ca3: SubcatchSnapshot? = s!!.subcatch
		this.subcatch = if (__ca3 === null) null else __ca3!!.Clone()
		val __ca4: GageSnapshot? = s!!.gages
		this.gages = if (__ca4 === null) null else __ca4!!.Clone()
		this.sys_temperature = s!!.sys_temperature
		this.sys_rainfall = s!!.sys_rainfall
		this.sys_snow_depth = s!!.sys_snow_depth
		this.sys_evap = s!!.sys_evap
